    // Parsed geometries, keyed by "<kind>:<style>" to avoid re-parsing on reuse.
    private static readonly Dictionary<string, PathGeometry> _cache = new();

    /// <summary>
    /// Returns the geometry for an application icon, or null when the kind has
    /// no geometry (e.g. <see cref="AppIconKind.None"/>).
    ///
    /// A fresh clone is returned on every call: WinUI 3's Path.Data rejects a
    /// Geometry instance that is already assigned to another Path ("Value does
    /// not fall within the expected range" / E_INVALIDARG), so the cached
    /// prototype must never be handed to more than one AppIcon.
    /// </summary>
    public static Geometry? GetGeometry(AppIconKind kind, bool filled)
    {
        if (kind == AppIconKind.None) return null;

        string figures;
        bool useFilled;
        if (filled && _filled.TryGetValue(kind, out var filledFigures))
        {
            figures = filledFigures;
            useFilled = true;
        }
        else if (_regular.TryGetValue(kind, out var regularFigures))
        {
            figures = regularFigures;
            useFilled = false;
        }
        else
        {
            Logger.Error($"AppIcons: no geometry registered for {kind}");
            return null;
        }

        string cacheKey = useFilled ? kind + ":F" : kind + ":R";
        if (!_cache.TryGetValue(cacheKey, out var prototype))
        {
            prototype = ParseGeometry(figures);
            if (prototype == null)
            {
                Logger.Error($"AppIcons: failed to parse geometry for {kind} (filled={filled})");
                return null;
            }
            _cache[cacheKey] = prototype;
        }
        return CloneGeometry(prototype);
    }

    /// <summary>
    /// Deep-copies a parsed PathGeometry (PathFigure + LineSegment/BezierSegment)
    /// so each AppIcon owns its own instance. ParseGeometry only ever produces
    /// those two segment types, so the clone is a faithful copy.
    /// </summary>
    private static PathGeometry CloneGeometry(PathGeometry source)
    {
        var clone = new PathGeometry { FillRule = source.FillRule };
        foreach (var figure in source.Figures)
        {
            var clonedFigure = new PathFigure
            {
                StartPoint = figure.StartPoint,
                IsClosed = figure.IsClosed,
                IsFilled = figure.IsFilled
            };
            foreach (var segment in figure.Segments)
            {
                switch (segment)
                {
                    case LineSegment line:
                        clonedFigure.Segments.Add(new LineSegment { Point = line.Point });
                        break;
                    case BezierSegment bezier:
                        clonedFigure.Segments.Add(new BezierSegment
                        {
                            Point1 = bezier.Point1,
                            Point2 = bezier.Point2,
                            Point3 = bezier.Point3,
                        });
                        break;
                }
            }
            clone.Figures.Add(clonedFigure);
        }
        return clone;
    }

    private static PathGeometry? ParseGeometry(string figures)
    {
        try
        {
            // Fluent path data uses only M/C/L/H/V/Z (absolute) commands. WinUI 3
            // has no TypeConverter for PathFigure, so string "Figures=..." cannot
            // be loaded via XamlReader — the geometry must be built by hand.
            var geometry = new PathGeometry { FillRule = FillRule.Nonzero };
            PathFigure? figure = null;
            char cmd = '\0';
            double cx = 0, cy = 0;

            int i = 0;
            while (i < figures.Length)
            {
                char c = figures[i];
                if (c == ' ' || c == ',' || c == '\t' || c == '\r' || c == '\n')
                {
                    i++;
                    continue;
                }

                if (char.IsLetter(c))
                {
                    cmd = c;
                    i++;
                    if (cmd == 'Z' || cmd == 'z')
                    {
                        if (figure != null) figure.IsClosed = true;
                        cmd = '\0';
                    }
                    continue;
                }

                if (cmd == '\0')
                {
                    Logger.Error($"AppIcons: coordinate without command in: {figures}");
                    return null;
                }

                switch (cmd)
                {
                    case 'M' or 'm':
                    {
                        double x1 = ReadNumber(figures, ref i);
                        double y1 = ReadNumber(figures, ref i);
                        if (cmd == 'm') { x1 += cx; y1 += cy; }
                        figure = new PathFigure { StartPoint = new Point(x1, y1) };
                        geometry.Figures.Add(figure);
                        cx = x1; cy = y1;
                        cmd = 'L'; // further coordinate pairs are implicit linetos
                        break;
                    }
                    case 'L' or 'l':
                    {
                        if (figure == null) return null;
                        double x1 = ReadNumber(figures, ref i);
                        double y1 = ReadNumber(figures, ref i);
                        if (cmd == 'l') { x1 += cx; y1 += cy; }
                        figure.Segments.Add(new LineSegment { Point = new Point(x1, y1) });
                        cx = x1; cy = y1;
                        break;
                    }
                    case 'C' or 'c':
                    {
                        if (figure == null) return null;
                        double x1 = ReadNumber(figures, ref i);
                        double y1 = ReadNumber(figures, ref i);
                        double x2 = ReadNumber(figures, ref i);
                        double y2 = ReadNumber(figures, ref i);
                        double x3 = ReadNumber(figures, ref i);
                        double y3 = ReadNumber(figures, ref i);
                        if (cmd == 'c') { x1 += cx; y1 += cy; x2 += cx; y2 += cy; x3 += cx; y3 += cy; }
                        figure.Segments.Add(new BezierSegment
                        {
                            Point1 = new Point(x1, y1),
                            Point2 = new Point(x2, y2),
                            Point3 = new Point(x3, y3),
                        });
                        cx = x3; cy = y3;
                        break;
                    }
                    case 'H' or 'h':
                    {
                        if (figure == null) return null;
                        double x1 = ReadNumber(figures, ref i);
                        if (cmd == 'h') x1 += cx;
                        figure.Segments.Add(new LineSegment { Point = new Point(x1, cy) });
                        cx = x1;
                        break;
                    }
                    case 'V' or 'v':
                    {
                        if (figure == null) return null;
                        double y1 = ReadNumber(figures, ref i);
                        if (cmd == 'v') y1 += cy;
                        figure.Segments.Add(new LineSegment { Point = new Point(cx, y1) });
                        cy = y1;
                        break;
                    }
                    default:
                        Logger.Error($"AppIcons: unsupported path command '{cmd}' in: {figures}");
                        return null;
                }
            }

            return geometry.Figures.Count == 0 ? null : geometry;
        }
        catch (Exception ex)
        {
            Logger.Error($"AppIcons: failed to parse geometry: {ex.Message}");
            return null;
        }
    }

    private static double ReadNumber(string figures, ref int i)
    {
        while (i < figures.Length && figures[i] == ' ') i++;
        int start = i;
        while (i < figures.Length)
        {
            char c = figures[i];
            if ((c >= '0' && c <= '9') || c == '-' || c == '+' || c == '.') i++;
            else if (c == 'e' || c == 'E')
            {
                int j = i + 1;
                if (j < figures.Length && (figures[j] == '-' || figures[j] == '+')) j++;
                if (j < figures.Length && figures[j] >= '0' && figures[j] <= '9') i = j + 1;
                else break;
            }
            else break;
        }
        return double.Parse(figures[start..i], CultureInfo.InvariantCulture);
    }
}
